mapper.select:
select event_id, worldline_id, screenshot_id, stage_id, event_title, event_date, event_year, event_type,
       country, related_forces, importance_level, divergence_flag, summary, ai_description,
       impact_analysis, novel_potential, create_by, create_time, update_by, update_time, remark
  from tl_event

    and worldline_id = #{worldlineId}
    and stage_id = #{stageId}
    and event_title like concat('%', #{eventTitle}, '%')
    and event_type = #{eventType}
    and importance_level = #{importanceLevel}
    and divergence_flag = #{divergenceFlag}

order by event_year asc, event_date asc, event_id asc

